ee:variables.ee:set-variable:
%dw 2.0
output application/java
fun toText(v) = v match {
	case is Null -> ""
	case s is String -> s
	case d is Date -> d as String {format: "yyyy-MM-dd"}
	case dt is DateTime -> dt as String {format: "yyyy-MM-dd"}
	case n is Number -> n as String
	case a is Array -> toText(a[0] default null)
	else -> ""
}
var s = toText(attributes.queryParams.fromDate)
---
if (s contains " ") ((s splitBy " ")[0] default "") else s

